import React from "react";
import { useTheme } from "@theme";

import Pie from "../subcomponents/pie";
import { DonutChartProps } from "../chart.types";

export const useDonutChart = (
  children: React.ReactNode,
  options: {
    innerRadius?: DonutChartProps["innerRadius"];
    outerRadius?: DonutChartProps["outerRadius"];
  },
) => {
  const theme = useTheme();
  const { innerRadius, outerRadius } = options;
  let pieCount = 0;
  let colorStartIndex = 0;

  if (!theme) {
    return {
      numCategoricalColors: 0,
      chartChildren: children,
    };
  }

  const categoricalColorKeys = Object.keys(theme.color.data.categorical).filter((key) =>
    key.endsWith("Default"),
  );
  const numCategoricalColors = categoricalColorKeys.length;
  const chartChildren = React.Children.map(children, (child) => {
    if (React.isValidElement(child) && child.type === Pie) {
      const pie = React.cloneElement(child, {
        pieIndex: pieCount,
        colorStartIndex,
        innerRadius: child.props.innerRadius || innerRadius,
        outerRadius: child.props.outerRadius || outerRadius,
      });
      pieCount++;
      colorStartIndex += child.props.data?.length || 0;
      return pie;
    }
    return child;
  });

  return { chartChildren, numCategoricalColors };
};
